/bin/bash -lc "node --input-type=module - <<'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'folio-restart-'));
const file = join(directory, 'books.json');
const origin = 'http://localhost:3098';
let child;
async function start() {
  child = spawn(process.execPath, ['server/index.js'], { cwd: process.cwd(), env: { ...process.env, PORT:'3098', NODE_ENV:'production', BOOKS_FILE:file }, stdio:['ignore','pipe','pipe'] });
  await new Promise((resolve,reject) => { child.stdout.on('data', chunk=>{if(chunk.toString().includes('Folió is ready')) resolve()}); child.on('error',reject); child.on('exit', code=>reject(new Error('Server exited '+code))); });
}
async function stop() { const exited = new Promise(resolve=>child.once('exit',resolve)); child.kill('SIGTERM'); await exited; child=null; }
async function call(path='',method='GET',body) { return fetch(origin+'/api/books'+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)}); }
try {
  await start();
  assert.deepEqual(await (await call()).json(), []);
  const added = await call('','POST',{title:'A book that survives',author:'A reader',notes:'First thought'});
  assert.equal(added.status,201);
  const book=await added.json();
  assert.ok(book.id);
  assert.equal((await call('/'+book.id)).status,200);
  const updated=await (await call('/'+book.id,'PATCH',{notes:'Saved notes\\nSecond line',status:'finished'})).json();
  assert.ok(updated.finishedAt);
  assert.equal(updated.status,'finished');
  await stop();
  await start();
  const persisted=await (await call('/'+book.id)).json();
  assert.equal(persisted.notes,'Saved notes\\nSecond line');
  assert.equal(persisted.status,'finished');
  assert.equal(persisted.id,book.id);
  const deepLink=await fetch(origin+'/books/'+book.id);
  assert.equal(deepLink.status,200);
  assert.match(await deepLink.text(),/id=\"root\"/);
  assert.equal((await call('','POST',{title:' ',author:'A'})).status,400);
  assert.equal((await call('/'+book.id,'PATCH',{status:'bad'})).status,400);
  assert.equal((await call('/missing')).status,404);
  await Promise.all(Array.from({length:12},(_,n)=>call('','POST',{title:'Concurrent '+n,author:'Reader'})));
  assert.equal((await (await call()).json()).length,13);
  assert.equal((await call('/'+book.id,'DELETE')).status,204);
  assert.equal((await call('/'+book.id)).status,404);
  assert.equal(JSON.parse(await readFile(file,'utf8')).length,12);
  console.log('PASS: create, update, finish, actual server restart, persistent notes and stable ID, direct shared URL, validation, concurrent adds, and delete.');
} finally { if(child) await stop(); await rm(directory,{recursive:true,force:true}); }
JS"

