const errors=[];
page.on('pageerror',e=>errors.push(e.message));
let addedId;
try {
  await page.goto(origin,{waitUntil:'networkidle'});
  await page.getByRole('button',{name:'Add a book',exact:true}).last().click();
  await page.getByLabel('Book title').fill('Browser test: A Small Reading Life');
