  await page.getByRole('button',{name:'Add to my library'}).click();
  await page.getByRole('dialog').waitFor({state:'hidden'});
  const allBooks=await (await fetch(origin+'/api/books')).json();
  addedId=allBooks.find(b=>b.title==='Browser test: A Small Reading Life').id;
  await page.getByRole('link',{name:'Browser test: A Small Reading Life',exact:true}).click();
  await page.getByRole('heading',{name:'Browser test: A Small Reading Life'}).waitFor();
  assert.equal(await page.getByLabel('My notes',{exact:true}).inputValue(),'My first reading note.');
  await page.getByLabel('My notes',{exact:true}).fill('A lasting thought.\\nThe next chapter is worth reading.');
  await page.getByRole('button',{name:'Save notes',exact:true}).click();
  await page.getByRole('button',{name:'Save notes',exact:true,disabled:true}).waitFor();
  await page.getByRole('button',{name:'Mark as finished',exact:true}).click();
  await page.getByRole('button',{name:'Read again',exact:true}).waitFor();
  await page.getByRole('button',{name:'Edit book',exact:true}).click();
