  await page.getByRole('button',{name:'Save changes',exact:true}).click();
  await page.getByRole('dialog').waitFor({state:'hidden'});
  await page.getByText('by A Different Reader',{exact:true}).waitFor();
  await page.getByRole('button',{name:'Share book',exact:true}).click();
  const link=await page.getByLabel('Book link',{exact:true}).inputValue();
  assert.equal(link,origin+'/books/'+addedId);
  await page.getByRole('button',{name:'Copy',exact:true}).click();
