  await visitor.close();
  await page.getByRole('button',{name:'Back to my library',exact:true}).click();
  await page.getByLabel('Search books').fill('A Different Reader');
  assert.equal(await page.locator('.book-card').count(),1);
  await page.getByRole('tab',{name:'Currently reading'}).click();
  assert.equal(await page.locator('.book-card').count(),0);
  await page.getByRole('tab',{name:'Finished'}).click();
