  await page.getByRole('link',{name:'Browser test: A Small Reading Life',exact:true}).click();
  await page.getByRole('button',{name:'Read again',exact:true}).click();
  await page.getByRole('button',{name:'Mark as finished',exact:true}).waitFor();
  await page.getByRole('button',{name:'Remove from library',exact:true}).click();
  await page.getByRole('button',{name:'Remove book',exact:true}).click();
  await page.locator('.page-heading h1').waitFor();
  assert.equal((await fetch(origin+'/api/books/'+addedId)).status,404);
  addedId=null;
  await page.setViewportSize({width:390,height:844});
